//! Non-destructive, Classic compound media: camera clock + one processed recorder.
use super::*;
#[derive(Deserialize,JsonSchema)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
struct Input {project_id:String,expected_revision:u64,#[schemars(length(min=2,max=2))] media_ids:Vec<String>}
#[derive(Serialize,JsonSchema)]
#[serde(rename_all="camelCase")]
struct Prepared {video_media_id:String,audio_media_id:String}
fn selected<'a>(assets:&'a [Map<String,Value>],ids:&[String])->Result<(&'a Map<String,Value>, &'a Map<String,Value>),CapabilityError>{
    if ids.len()!=2||ids[0]==ids[1]{return Err(invalid("Select one video or Unified Angles and one external audio recording"));}
    let mut chosen=ids.iter().map(|id|assets.iter().find(|a|a["id"]==*id).ok_or_else(||invalid("Selected media is missing"))).collect::<Result<Vec<_>,_>>()?;
    chosen.sort_by_key(|a|a["type"]!="video");let(v,a)=(chosen[0],chosen[1]);
    if v["type"]!="video"||a["type"]!="audio"{return Err(invalid("Select one video or Unified Angles and one external audio recording"));}
    let u=metadata(v).map_err(|e|invalid(&e))?;
    let ids=u.as_ref().map(|u|u.angle_asset_ids.clone()).unwrap_or_else(||vec![v["id"].as_str().unwrap().into()]);
    for id in ids.iter().chain(std::iter::once(&a["id"].as_str().unwrap().to_owned())) {
        let source=assets.iter().find(|s|s["id"]==*id).ok_or_else(||invalid("Compound source is missing"))?;
        if source["missing"]==true||source["hasAudio"]==false||!source["duration"].as_f64().is_some_and(|d|d.is_finite()&&d>0.){return Err(invalid("Every selected source needs available reference audio and a known duration"));}
    }
    Ok((v,a))
}
/// Only insertion initializes processing. Later manual edits, splits and take
/// swaps retain their own parameters; source media are never processed in place.
pub(in crate::operations) fn prepare_element(e:&mut Value,assets:&[Map<String,Value>])->Res
